8315:     $panelInfo = Get-PropertyValue $Record 'panel' $null
8316:     $isPanel = ($null -ne $panelInfo)
8317:     if ($isPanel) {
8318:         $panelId = [string](Get-PropertyValue $panelInfo 'id' '')
8319:         $what += ", review panel $($panelId.Substring(0, [Math]::Min(8, $panelId.Length))) member $(Get-PropertyValue $panelInfo 'position' '?')"
